    metaKeywords: ['hades 2 advanced guide', 'hades 2 builds', 'hades 2 fear', 'hades 2 surface'],
    author: 'GameGuide Team', published: true, views: 0, likes: 0, readingTime: 15,
    publishedAt: '2026-06-02', updatedAt: '2026-06-02',
